package main

import (
	"encoding/json"
	"net/http"
	"net/http/httptest"
	"strings"
	"testing"
	"time"
)

func TestProbeByUser(t *testing.T) {
	store := NewStore(time.Hour)
	// alice: two sessions created out of order (1002 first, then 1001).
	now := time.Unix(1002, 0)
	store.now = func() time.Time { return now }
	store.Create("a2", "alice")
	now = time.Unix(1001, 0)
	store.now = func() time.Time { return now }
	store.Create("a1", "alice")
	now = time.Unix(1003, 0)
	store.now = func() time.Time { return now }
	store.Create("b1", "bob")

	mux := http.NewServeMux()
	mux.HandleFunc("/session", sessionHandler(store))
	mux.HandleFunc("/sessions", sessionsHandler(store))

	rec := httptest.NewRecorder()
	mux.ServeHTTP(rec, httptest.NewRequest("GET", "/sessions?user=alice", nil))
	if rec.Code != http.StatusOK {
		t.Fatalf("status = %d, want 200", rec.Code)
	}
	var got []Session
	if err := json.Unmarshal(rec.Body.Bytes(), &got); err != nil {
		t.Fatalf("body: %v", err)
	}
	if len(got) != 2 {
		t.Fatalf("got %d sessions, want 2", len(got))
	}
	if got[0].ID != "a1" || got[1].ID != "a2" {
		t.Fatalf("order = [%s %s], want [a1 a2] (Created ascending)", got[0].ID, got[1].ID)
	}

	// Expired alice session must be excluded.
	now = time.Unix(1004, 0)
	store.now = func() time.Time { return now }
	store.Create("a3", "alice")
	now = time.Unix(999999, 0) // far future: a1/a2/a3 all expired (ttl 1h)
	store.now = func() time.Time { return now }
	rec = httptest.NewRecorder()
	mux.ServeHTTP(rec, httptest.NewRequest("GET", "/sessions?user=alice", nil))
	var after []Session
	_ = json.Unmarshal(rec.Body.Bytes(), &after)
	if len(after) != 0 {
		t.Fatalf("expired sessions listed: %d", len(after))
	}

	// Restore the clock for the remaining checks.
	now = time.Unix(1003, 0)
	store.now = func() time.Time { return now }

	// Missing user param: 400.
	rec = httptest.NewRecorder()
	mux.ServeHTTP(rec, httptest.NewRequest("GET", "/sessions", nil))
	if rec.Code != http.StatusBadRequest {
		t.Fatalf("missing user status = %d, want 400", rec.Code)
	}

	// Unknown user: empty array, not null.
	rec = httptest.NewRecorder()
	mux.ServeHTTP(rec, httptest.NewRequest("GET", "/sessions?user=nobody", nil))
	if rec.Code != http.StatusOK {
		t.Fatalf("unknown user status = %d, want 200", rec.Code)
	}
	if strings.TrimSpace(rec.Body.String()) == "null" {
		t.Fatal("unknown user must return an empty JSON array, not null")
	}
}
EOF
go test -count=1 . ; rc=$? ; rm -f probe_byuser_test.go ; exit $rc

